add('lv','左心室','尺寸：ASE/EACVI 2015；GLS：ASE/EACVI 2025共识',[
h('线性尺寸与室壁厚度'),t(['指标','男性','女性'],[['LVIDd · 舒张末内径','42–58 mm','38–52 mm'],['LVIDs · 收缩末内径','25–40 mm','22–35 mm'],['LVIDd / BSA','22–30 mm/m²','23–31 mm/m²'],['IVSd / PWd · 室间隔 / 后壁厚度','6–10 mm','6–9 mm'],['FS · 短轴缩短率','25–43%','27–45%'],['左室质量指数 LVMi','49–115 g/m²','43–95 g/m²']]),
h('左室扩大与室壁增厚'),t(['指标','正常','轻度','中度','重度'],[['男性 LVIDd（mm）','42–58','59–63','64–68','>68'],['女性 LVIDd（mm）','38–52','53–56','57–61','>61'],['男性 IVS/PW（mm）','6–10','11–13','14–16','>16'],['女性 IVS/PW（mm）','6–9','10–12','13–15','>15']]),
f('RWT = 2 × PWd / LVIDd'),t(['相对壁厚','左室质量正常','左室质量增高'],[['RWT ≤0.42','正常构型','离心性肥厚'],['RWT >0.42','向心性重构','向心性肥厚']]),
h('双平面 Simpson 容积'),t(['指标','男性','女性'],[['EDV · 舒张末容积','62–150 mL','46–106 mL'],['ESV · 收缩末容积','21–61 mL','14–42 mL'],['EDVi · 舒张末容积指数','34–74 mL/m²','29–61 mL/m²'],['ESVi · 收缩末容积指数','11–31 mL/m²','8–24 mL/m²']]),
h('收缩功能'),t(['LVEF','正常','轻度降低','中度降低','重度降低'],[['男性','52–72%','41–51%','30–40%','<30%'],['女性','54–74%','41–53%','30–40%','<30%']]),
p('心衰按 LVEF 分类：HFrEF ≤40%；HFmrEF 41–49%；HFpEF ≥50%。心衰诊断还需要临床及客观证据，不能仅凭 EF。HFimpEF 的定义依指南而异：2022 AHA/ACC/HFSA 为既往 ≤40%、随访 >40%；部分通用定义另要求绝对升高 ≥10 个百分点。'),
p('GLS（整体纵向应变）通常约 −20%。数值受厂家、年龄及负荷影响；比 −18% 更负一般较好，比 −16% 更接近0提示异常可能。肿瘤治疗随访中，相对下降 >15% 是需要结合其他指标评估的信号。'),
n('SVi <35 mL/m² 可提示低流量。LVOT VTI 常见约18–22 cm，但低 VTI 不能单独诊断低心排量。MR dP/dt >1200 mmHg/s 通常较好，<1000 提示收缩功能受损可能；受负荷及反流频谱质量影响。')]);
add('segments','17节段与冠脉供血','ASE 17节段模型 · 供血分区为典型分布，存在个体差异',[{type:'segments'},
t(['层面','节段名称'],[['基底段 1–6','1 前壁；2 前间隔；3 下间隔；4 下壁；5 下外侧壁；6 前外侧壁'],['中间段 7–12','7 前壁；8 前间隔；9 下间隔；10 下壁；11 下外侧壁；12 前外侧壁'],['心尖段 13–16','13 前壁；14 间隔；15 下壁；16 侧壁'],['心尖帽 17','心尖顶端']]),
t(['冠脉','典型供血节段'],[['LAD · 左前降支','1、2、7、8、13、14、17'],['RCA · 右冠状动脉','3、4、9、10、15'],['LCx · 左回旋支','5、6、11、12、16']]),
n('冠脉优势型、分支长度与个体解剖会改变供血范围。二维室壁运动评分通常采用16节段，不把难以可靠评价增厚的心尖帽纳入；本工具默认17号不评分。'),
p('评分：1 正常或运动增强；2 运动减弱；3 无运动；4 反常运动（收缩期向外膨出）。WMSI = 已评分节段分数之和 ÷ 已评分节段数。正常为1。'),
p('不符合单一冠脉分布的异常还应考虑 Takotsubo、心肌炎、结节病，以及左束支阻滞或起搏相关的室间隔运动异常。薄而高回声的室壁提示瘢痕可能，但不能单凭厚度确诊。')]);
add('walls','切面与室壁对应','按标准屏幕方位示意 · 实际以解剖标志确认',[{type:'walls'},t(['切面','一侧室壁','对侧室壁'],[['PLAX','上方：前间隔 2、8','下方：下外侧壁 5、11'],['A4C','屏幕左侧：下间隔 3、9、心尖间隔14','屏幕右侧：前外侧壁6、12、心尖侧壁16'],['A2C','屏幕左侧：下壁4、10、15','屏幕右侧：前壁1、7、13'],['A3C','屏幕左侧：下外侧壁5、11','屏幕右侧：前间隔2、8'],['PSAX','基底 / 中段各6节段','心尖层4节段']]),
p('记忆：四腔心看下间隔和前外侧壁；长轴看前间隔和下外侧壁；两腔心看下壁和前壁。传统“后壁”名称在标准节段模型中对应下外侧壁。'),
p('PSAX 钟面：12点前壁，2点前外侧壁，4点下外侧壁，6点下壁，8点下间隔，10点前间隔。探头方向与显示习惯不同，需用右室和瓣膜等标志核实。'),
p('常见旋转顺序：A4C → 约60°逆时针 → A2C → 再约60° → A3C；角度只作操作参考。A3C 的心尖切面介于标准心尖分区之间，结合 A4C、A2C 定位。'),
n('前外侧乳头肌常有 LAD 对角支及 LCx 双重供血；后内侧乳头肌通常主要由后降支供血，来源随冠脉优势型改变。')]);
add('diastolic','舒张功能','ASE 2025 · Figure 3：窦性心律下分级与左房压评估',[
n('不再使用2016版“四项过半”作为本栏算法。适用于窦性心律；房颤、任何程度MS、重度原发MR、中重度MAC、二尖瓣介入/术后、LVAD、移植、非心源性肺高压及缩窄不适用。'),
t(['首轮指标','异常界值'],[['e′','间隔 ≤6；侧壁 ≤7；或平均 ≤6.5 cm/s（也可按年龄校正）'],['E/e′','间隔 ≥15；侧壁 ≥13；或平均 ≥14'],['肺动脉压力','PASP ≥35 mmHg；RAP 无法估测时用 TR ≥2.8 m/s']]),
t(['组合','下一步'],[['三项均正常','左房压正常，舒张功能正常'],['三项均异常','左房压升高：E/A <2 → Ⅱ级；E/A ≥2 → Ⅲ级'],['仅 e′ 降低，且 E/A ≤0.8','Ⅰ级，左房压正常'],['其他组合，或仅 e′ 降低且 E/A >0.8','补充肺静脉 S/D ≤0.67、LASr ≤18%、LAVI >34；可替代用 IVRT ≤70 ms。可靠阳性支持左房压升高；均不支持则倾向正常左房压。']]),
n('补充指标也有适用限制；肺静脉 S/D 在 EF 正常者的阴性排除能力有限。静息压正常但有症状者可进一步做舒张负荷超声。计算器只给可用数据的流程提示，不把缺测当成正常。')]);
add('atria','左房与右房','左房：ASE/EACVI 2015；右房：ASE 2025 · 按方法区分参考值',[
t(['指标','正常','轻度扩大','中度扩大','重度扩大'],[['左房容积指数 LAVI','16–34 mL/m²','35–41','42–48','>48']]),
t(['指标','参考值','提示'],[['LA 前后径（PLAX）','男30–40 mm；女27–38 mm','单一径线可能低估左房扩大，优先使用容积'],['RA 容积指数（2025，盘叠法）','<30 mL/m²','面积-长度法 <33；3D收缩末 <42 mL/m²；不同方法不混用'],['RA 面积（2025）','<19 cm²','2022 PH概率算法中的 >18 cm² 是另一用途阈值'],['RA 长轴 / 短轴（2025）','<54 / <42 mm','结合体型、容积及右心状态']]),
n('心房容积在心室收缩末、房室瓣开放前测量；使用心房聚焦切面，避免缩短。左房描记排除肺静脉与左心耳。')]);
add('rv','右心室','ASE 2025 · Table 1；应变采用绝对值',[
t(['尺寸 / 面积','正常参考'],[['基底径 / 中段径 / 长径','<41 / <35 / <82 mm'],['RVOT：PLAX / PSAX近端 / PSAX远端','<33 / <34 / <29 mm'],['右室游离壁厚','<5 mm'],['右室舒张末面积','<25 cm²；指数 <14 cm²/m²']]),
t(['收缩功能','正常','轻度异常','中度异常','重度异常'],[['TAPSE（mm）','>17','>13–17','>10–13','≤10'],['S′（cm/s）','>9.5','>7.2–9.5','>5.0–7.2','≤5.0'],['FAC（%）','>35','>29–35','>22–29','≤22'],['3D RVEF（%）','>45','>39–45','32–39','<32'],['游离壁应变绝对值（%）','>20','15–20','11–<15','<11']]),
f('FAC = (EDA − ESA) / EDA × 100%'),
p('右室聚焦四腔心测量；纵向指标不能代表全部右室收缩。结合 FAC、3D容积、应变、负荷和临床。手术后或显著TR时尤其注意。'),
p('D形左室：收缩期室间隔扁平偏向压力负荷；舒张期偏向容量负荷；可并存。McConnell征并非肺栓塞特异。'),
n('2025版正常边界使用严格 > 或 <，与截图旧表不同。本栏已同步更新。')]);
add('ph','右房压与肺高压','IVC 传统估算；ESC/ERS 2022 肺高压超声概率',[
t(['IVC 内径','快速吸气塌陷','估测 RAP'],[['≤21 mm','>50%','3 mmHg（0–5）'],['≤21 mm','≤50%','8 mmHg（5–10）'],['>21 mm','>50%','8 mmHg（5–10）'],['>21 mm','≤50%','15 mmHg（10–20）']]),n('IVC 法适用于自主呼吸；机械通气时不能直接套用。IVC 在距右房入口约1–2 cm处测量，需结合肝静脉和其他右心征象。'),
t(['TR 峰值流速','其他 PH 征象','超声概率'],[['≤2.8 m/s 或无法测得','无','低'],['≤2.8 m/s 或无法测得','有','中'],['>2.8–3.4 m/s','无','中'],['>2.8–3.4 m/s','有','高'],['>3.4 m/s','不作必要条件','高']]),
t(['征象类别','支持线索'],[['A · 心室','RV/LV >1；室间隔扁平（偏心指数 >1.1）；TAPSE/PASP <0.55'],['B · 肺动脉','RVOT AcT <105 ms 或收缩中期切迹；早期 PR >2.2 m/s；PA 直径 >25 mm 或大于主动脉根部'],['C · IVC / 右房','IVC >21 mm 且吸气塌陷减少；RA 收缩末面积 >18 cm²']]),
n('“有其他征象”应来自至少两类（A/B/C），不是同一类内凑两项。超声评估概率，肺高压的确诊和分类需要结合临床，必要时右心导管。无 TR 信号不等于无肺高压。')]);
add('as','主动脉瓣狭窄 AS','ASE/EACVI 2017 定量；ESC/EACTS 2025 管理更新',[
t(['指标','轻度','中度','重度'],[['Vmax（m/s）','2.6–2.9','3.0–3.9','≥4.0'],['平均压差（mmHg）','<20','20–39','≥40'],['AVA（cm²）','>1.5','1.0–1.5','<1.0'],['AVAi（cm²/m²）','>0.85','0.60–0.85','<0.60'],['DVI','>0.50','0.25–0.50','<0.25']]),
p('表为 ASE 定量分级；ACC/AHA 分期的轻度峰速下限为2.0 m/s，不能把两套体系混写。正常 AVA 约3–4 cm²。极重度线索：Vmax ≥5 m/s 或平均压差 ≥60 mmHg。'),
f('AVA = (π × LVOT直径² / 4 × LVOT VTI) / AV VTI'),
n('AVA 与压差不一致时先检查 LVOT 内径、PW取样位置、CW声束对齐和血压；直径误差会被平方放大。SVi ≤35 mL/m² 为低流量常用界值，边界应结合测量误差。'),
p('低流量低压差：LVEF <50% 为经典型，LVEF ≥50% 为矛盾型。结合低剂量多巴酚丁胺负荷、流量变化及CT瓣膜钙化，而非只凭静息 AVA。CT钙化评分需按性别及具体指南解读。'),
p('2025 ESC/EACTS：无症状重度高压差AS、LVEF ≥50%、低操作风险时，可考虑早期干预作为严密随访的替代（IIa A；可行时运动试验证实无症状）。LVEF <50%且无其他原因则为I类推荐。')]);
add('ar','主动脉瓣反流 AR','ASE 2017 定量；ESC/EACTS 2025 管理更新',[
t(['指标','轻度','中度','重度'],[['缩流颈 VC（cm）','<0.3','0.3–0.6','>0.6'],['反流束宽 / LVOT','<25%','25–64%','≥65%'],['PHT（ms）','>500','200–500','<200'],['反流量 RVol（mL）','<30','30–59','≥60'],['反流分数 RF','<30%','30–49%','≥50%'],['EROA（cm²）','<0.10','0.10–0.29','≥0.30'],['降主动脉反向血流','短暂早期','中间表现','全舒张期；舒张末速度 ≥20 cm/s 为重要线索']]),
n('PHT 受主动脉 / 左室顺应性与血压影响。急性重度AR可没有左室扩大。偏心束不能只按彩色面积判断。'),
p('2025 ESC/EACTS：重度AR应结合症状及左室尺寸/功能评估干预；低风险、无症状患者的较早评估还纳入 LVESDi >22 mm/m²、LVESVi >45 mL/m² 或 LVEF ≤55%（IIb，非一律手术）。具体推荐等级与临床条件见原指南。')]);
add('ms','二尖瓣狭窄 MS','ACC/AHA 2020 分期；ESC/EACTS 2025 临床管理',[
t(['项目','参考与解释'],[['MVA · 瓣口面积','≤1.5 cm²：临床显著风湿性MS；≤1.0 cm² 提示非常严重的狭窄'],['平均跨瓣压差','受心率、节律、流量和MR影响，必须同时记录心率；不能单独代替瓣口面积'],['直接描记','PSAX瓣尖最小开口，注意切面与增益；必要时3D辅助'],['PHT 法','MVA = 220 / PHT；球囊扩张后、顺应性异常、明显AR等不可靠']]),
p('Wilkins评分：活动度、增厚、钙化和瓣下病变，各1–4分；≤8分通常较有利，但不能替代交界钙化、MR及左房血栓评估。经皮交界切开还需排除左房血栓及超过轻度MR等禁忌。'),
n('风湿性：交界融合、前叶穹隆样开放、腱索增厚。退行性MAC相关MS机制不同，不能直接套用风湿性MS的介入选择标准。')]);
add('mr','二尖瓣反流 MR','ASE 2017 定量；ESC/EACTS 2025 · 原发与继发分开评估',[
t(['指标','轻度','中度','重度（原发MR）'],[['VC（cm）','<0.3','0.3–0.69','≥0.7'],['EROA（cm²）','<0.20','0.20–0.39','≥0.40'],['RVol（mL）','<30','30–59','≥60'],['RF','<30%','30–49%','≥50%'],['肺静脉血流','S占优','S减低','收缩期逆流'],['CW频谱','淡 / 不完整','致密','致密；可呈早达峰三角形'],['结构','可正常','依病因','连枷瓣、腱索 / 乳头肌断裂、明显对合缺损等']]),
p('Carpentier：Ⅰ型活动正常（瓣环扩大、穿孔）；Ⅱ型活动过度（脱垂、连枷）；Ⅲa型收缩和舒张均受限（如风湿）；Ⅲb型收缩期受限（如缺血性牵拉）。'),
p('A1/P1 位于外侧、靠左心耳；A2/P2居中；A3/P3位于内侧。脱垂反流束常指向病变瓣叶的对侧，但需多切面证实。'),
n('继发MR存在低流量、椭圆/新月形反流口及动态变化，PISA可能低估。2025 ESC/EACTS强调 EROA ≥0.30 cm² 和/或 RVol ≥45 mL 已可具有重要预后及治疗意义；不能机械套用原发MR阈值排除严重病变。先优化心衰治疗、评估CRT适应证，再由团队判断干预。'),
p('重度原发MR：LVEF ≤60%、LVESD ≥40 mm是重要左室受累标志；2025 ESC另纳入 LVESDi ≥20 mm/m²。症状、房颤、肺动脉压力、左房扩大及修复可能性也影响时机。')]);
add('tv','三尖瓣','ASE 2017 定量；ASE 2025 右心；ESC/EACTS 2025 管理',[
t(['TR指标','轻度','中度','重度'],[['VC（cm）','<0.3','0.3–0.69','≥0.7'],['EROA（cm²）','<0.20','0.20–0.39','≥0.40'],['RVol（mL）','<30','30–44','≥45'],['肝静脉','S占优','S减低','收缩期逆流'],['CW','较淡，抛物线','致密','致密、早达峰三角形']]),
p('扩展五级法可将重度以上进一步分为 severe、massive、torrential，用于描述极重反流及介入疗效；不同量化方法的界值不能互换，本表采用常规三级法。'),
n('显著TR可能低估TR压差；结合右室、右房、IVC及肝静脉。2025管理强调在右室或终末器官损害进展前评估干预，合并左侧瓣膜手术时需同时评估三尖瓣。'),
h('三尖瓣狭窄 TS'),p('平均压差 ≥5 mmHg、PHT ≥190 ms、TVA ≤1.0 cm²、流入道 VTI ≥60 cm 支持显著狭窄；结合心率、呼吸及流量。')]);
add('pv','肺动脉瓣','ASE 瓣膜狭窄 / 原生瓣反流定量；结合2025右心评估',[
t(['PS 指标','轻度','中度','重度'],[['Vmax（m/s）','<3','3–4','>4'],['峰值压差（mmHg）','<36','36–64','>64']]),
t(['PR 线索','解释'],[['反流束宽 / 瓣环','>70% 提示重度可能'],['CW / PHT','致密、快速减速；PHT <100 ms 支持重度，但受压力与顺应性影响'],['PR index','<0.77 支持重度（反流时限 / 总舒张时限）'],['CMR 反流分数','<20%轻；20–40%中；>40%重（方法与临床背景需注明）'],['分支肺动脉血流','舒张期逆流支持显著PR']]),
f('PADP ≈ 4 × PR舒张末速度² + RAP'),f('mPAP ≈ 4 × PR早期峰值速度² + RAP'),n('速度单位 m/s，压力单位 mmHg。复杂先心病、术后RVOT或多处梗阻须专门评估。')]);
add('prosthesis','人工瓣膜','ASE 2024 · 已更新主动脉人工瓣DVI，按瓣型/尺寸与基线对照',[
h('外科主动脉人工瓣 SAVR'),t(['指标','正常参考','可能狭窄','提示显著狭窄'],[['峰速（m/s）','<3','3–4','≥4'],['平均压差（mmHg）','<20','20–34','≥35'],['DVI','>0.35','0.25–0.35','<0.25'],['加速时间 AT（ms）','<80','80–100','>100'],['AT / ET','<0.32','0.32–0.37','>0.37']]),
p('EOA 应与该瓣型、尺寸的正常参考值比较，不再统一按固定1.2/0.8 cm²划分。TAVI更重视与稳定术后基线相比的压差、DVI、EOA变化。至少结合一个流量依赖和一个相对不依赖流量的参数。'),
h('二尖瓣人工瓣'),t(['指标','正常参考','可能狭窄','提示显著狭窄'],[['峰值 E（m/s）','<1.9','1.9–2.5','≥2.5'],['平均压差（mmHg）','≤5','6–10','>10'],['VTI_MV / VTI_LVOT','<2.2','2.2–2.5','>2.5'],['EOA（cm²）','≥2.0','1–2','<1'],['PHT（ms）','<130','130–200','>200']]),
n('注明心率。高压差可能来自高流量、患者-人工瓣不匹配、反流或梗阻；结合瓣叶活动及基线，必要时TEE、CT。PHT 不用于计算人工二尖瓣面积。')]);
add('aorta','主动脉','成人尺寸参考；ACC/AHA 2022 主动脉疾病管理',[
t(['部位','男性（均值±SD）','女性（均值±SD）'],[['瓣环','26±3 mm','23±2 mm'],['Valsalva窦','34±3 mm','30±3 mm'],['窦管交界 STJ','29±3 mm','26±3 mm'],['近端升主动脉','30±4 mm','27±4 mm']]),
n('这些是人群均值，不是手术或异常的统一界值。根部/升主动脉传统TTE采用舒张末前缘到前缘；瓣环采用收缩中期内缘到内缘。随访保持方法一致，并考虑体型、年龄、性别。'),
p('手术阈值依散发性、二叶瓣、遗传性主动脉病、增长速度及是否同期瓣膜手术而不同。常见散发性根部/升主动脉阈值为55 mm，经验团队可对选定患者采用50 mm；不能把“同期其他任何心脏手术”一律写成45 mm。')]);
add('pericardium','心包','ESC 2025 心肌炎与心包炎指南 · 超声核心线索',[
t(['积液程度','舒张末无回声间隙'],[['少量','<10 mm'],['中量','10–20 mm'],['大量','>20 mm']]),
p('压塞线索：右房塌陷、右室舒张期塌陷、IVC充盈且塌陷减少、二尖瓣/三尖瓣流入速度随呼吸明显变化。积液量不等于血流动力学影响，压塞是综合临床诊断。'),
p('缩窄线索：呼吸相关室间隔位移，内侧 e′ 相对保留（常≥9 cm/s），内侧 e′ 大于外侧（annulus reversus），肝静脉呼气期舒张逆流增强。心包不厚也不能排除缩窄。'),
n('PLAX鉴别：心包积液一般位于降主动脉前方；胸腔积液在其后方。前方颗粒状、随心脏运动的低回声区可为心外膜脂肪。呼吸变异阈值受机械通气、房颤及肺病影响。')]);
add('hcm','心肌病与血栓','HCM：AHA/ACC 2024；其他为鉴别诊断线索',[
p('HCM：不能用负荷解释的最大室壁厚度 ≥15 mm；家族史/基因阳性时13–14 mm也需进一步评估。全左室多切面测量，避免把右室肌束计入室间隔。'),
p('LVOT梗阻：静息或诱发峰值压差 ≥30 mmHg；≥50 mmHg是讨论梗阻相关治疗的重要阈值，仍需结合症状与治疗反应。可用Valsalva、站立、运动诱发；CW常为晚达峰匕首形，注意与MR频谱区分。'),
p('淀粉样变线索：室壁增厚、双房扩大、少量心包积液及应变“心尖保留”。心电低电压并非必有，心尖保留也不是特异诊断。'),
p('左室血栓：心尖无运动/室壁瘤区域的团块，至少两切面确认；心尖显示欠佳时考虑超声增强剂或CMR。')]);
add('formulas','常用公式','单位必须一致 · 经验压力公式不是有创测量替代',[
h('血流与心排量'),f('ΔP（mmHg）= 4 × V²（V：m/s）；近端速度不可忽略时：4 × (V₂² − V₁²)'),f('LVOT面积（cm²）= π × d² / 4（d：cm）\nSV（mL）= LVOT面积 × LVOT VTI（cm）\nCO（L/min）= SV × HR / 1000\nCI = CO / BSA；SVi = SV / BSA\nQp/Qs = (RVOT直径² × RVOT VTI) / (LVOT直径² × LVOT VTI)'),
h('压力'),f('RVSP = 4 × TRV² + RAP\n无RVOT/肺动脉瓣梗阻时，PASP ≈ RVSP\nPADP ≈ 4 × PR舒张末速度² + RAP\nmPAP ≈ 4 × PR早期峰值速度² + RAP\nPVR（WU）≈ 10 × TRV（m/s）/ RVOT VTI（cm）+ 0.16'),
n('mPAP = 79 − 0.45 × AcT、LAP = 1.24 × E/e′ +1.9 等经验回归式不能可靠给出个体精确压力，本版不用于自动诊断。LVEDP = 舒张压 − 4 × AR舒张末速度² 仅在适当条件下近似。'),
h('瓣膜'),f('AVA = LVOT面积 × LVOT VTI / AV VTI\nDVI = LVOT VTI / AV VTI\nMVA（cm²）= 220 / PHT（ms）\nPISA流量（mL/s）= 2π × r²（cm²）× Va（cm/s）\nEROA（cm²）= PISA流量 / 反流峰速（cm/s）\nRVol（mL）= EROA × 反流VTI（cm）'),
h('左心室与体表面积'),f('LV质量（g）= 0.8 × 1.04 × [(IVS + LVIDd + PW)³ − LVIDd³] + 0.6（尺寸用cm）\nRWT = 2 × PWd / LVIDd\nFS（%）= (LVIDd − LVIDs) / LVIDd × 100\nLVEF（%）= (EDV − ESV) / EDV × 100\ndP/dt（mmHg/s）= 32000 / Δt（ms；MR速度从1至3 m/s）\nMPI = (IVCT + IVRT) / ET\nBSA（m²）= √[身高（cm）× 体重（kg）/ 3600]')]);
add('calculators','计算器','输入后即时计算 · 全部运算在当前页面完成',[{type:'calculators'}]);
